'use strict';

const fs = require('fs');
const input = fs.readFileSync(0);
let ptr = 0;

function nextInt() {
  while (ptr < input.length && input[ptr] <= 32) ptr++;
  let value = 0;
  while (ptr < input.length && input[ptr] > 32) {
    value = value * 10 + input[ptr] - 48;
    ptr++;
  }
  return value;
}

const N = nextInt();
const M = nextInt();
const K = nextInt();

const prices = new Int32Array(K + 1);
for (let i = 1; i <= K; i++) prices[i] = nextInt();

const U = new Int32Array(M);
const V = new Int32Array(M);
const T = new Int32Array(M);
const order = new Array(M);

for (let i = 0; i < M; i++) {
  U[i] = nextInt();
  V[i] = nextInt();
  T[i] = nextInt();
  order[i] = i;
}

const A = nextInt();
const B = nextInt();

order.sort((a, b) => T[a] - T[b]);

const parent = new Int32Array(N + 1);
const size = new Int32Array(N + 1);
const stamp = new Int32Array(N + 1);
const rootComp = new Int32Array(N + 1);
const compStamp = new Int32Array(N + 1);

let token = 0;
let compCount = 0;
const compPrice = [0];
const pairs = [];
const BASE = M + 1;

function find(x) {
  if (stamp[x] !== token) {
    stamp[x] = token;
    parent[x] = x;
    size[x] = 1;
  }

  let r = x;
  while (parent[r] !== r) r = parent[r];

  while (parent[x] !== x) {
    const next = parent[x];
    parent[x] = r;
    x = next;
  }
  return r;
}

function getCompId(root, type) {
  if (compStamp[root] !== token) {
    compStamp[root] = token;
    rootComp[root] = ++compCount;
    compPrice[compCount] = prices[type];
  }
  return rootComp[root];
}

let start = 0;
while (start < M) {
  const type = T[order[start]];
  let end = start + 1;
  while (end < M && T[order[end]] === type) end++;

  token++;

  for (let p = start; p < end; p++) {
    const i = order[p];
    let a = find(U[i]);
    let b = find(V[i]);

    if (a !== b) {
      if (size[a] < size[b]) {
        const tmp = a;
        a = b;
        b = tmp;
      }
      parent[b] = a;
      size[a] += size[b];
    }
  }

  for (let p = start; p < end; p++) {
    const i = order[p];
    const a = getCompId(find(U[i]), type);
    const b = getCompId(find(V[i]), type);
    pairs.push(U[i] * BASE + a);
    pairs.push(V[i] * BASE + b);
  }

  start = end;
}

pairs.sort((a, b) => a - b);

const nodeCount = N + compCount;
const head = new Int32Array(nodeCount + 1);
head.fill(-1);

const maxEdges = pairs.length * 2;
const to = new Int32Array(maxEdges);
const next = new Int32Array(maxEdges);
const weight = new Uint16Array(maxEdges);
let edgeCount = 0;

function addEdge(from, dest, cost) {
  to[edgeCount] = dest;
  weight[edgeCount] = cost;
  next[edgeCount] = head[from];
  head[from] = edgeCount++;
}

let previous = -1;
for (const encoded of pairs) {
  if (encoded === previous) continue;
  previous = encoded;

  const station = Math.floor(encoded / BASE);
  const cid = encoded - station * BASE;
  const componentNode = N + cid;

  addEdge(station, componentNode, compPrice[cid]);
  addEdge(componentNode, station, 0);
}

const dist = new Float64Array(nodeCount + 1);
dist.fill(Infinity);
const position = new Int32Array(nodeCount + 1);
const heap = new Int32Array(nodeCount + 1);
let heapSize = 1;

dist[A] = 0;
heap[1] = A;
position[A] = 1;

while (heapSize > 0) {
  const current = heap[1];
  const currentDist = dist[current];

  position[current] = -1;
  const last = heap[heapSize--];

  if (heapSize > 0) {
    heap[1] = last;
    position[last] = 1;

    let i = 1;
    while (true) {
      const left = i * 2;
      const right = left + 1;
      let smallest = i;

      if (left <= heapSize && dist[heap[left]] < dist[heap[smallest]]) {
        smallest = left;
      }
      if (right <= heapSize && dist[heap[right]] < dist[heap[smallest]]) {
        smallest = right;
      }
      if (smallest === i) break;

      const tmp = heap[i];
      heap[i] = heap[smallest];
      heap[smallest] = tmp;
      position[heap[i]] = i;
      position[heap[smallest]] = smallest;
      i = smallest;
    }
  }

  if (current === B) break;

  for (let e = head[current]; e !== -1; e = next[e]) {
    const neighbor = to[e];
    if (position[neighbor] === -1) continue;

    const candidate = currentDist + weight[e];
    if (candidate >= dist[neighbor]) continue;

    dist[neighbor] = candidate;
    let i = position[neighbor];

    if (i === 0) {
      i = ++heapSize;
      heap[i] = neighbor;
    }

    while (i > 1) {
      const parentIndex = i >> 1;
      if (dist[heap[parentIndex]] <= dist[neighbor]) break;

      heap[i] = heap[parentIndex];
      position[heap[i]] = i;
      i = parentIndex;
    }

    heap[i] = neighbor;
    position[neighbor] = i;
  }
}

console.log(Number.isFinite(dist[B]) ? String(dist[B]) : '-1');
